"""Independent reference implementation of the replay contract, written from
the spec text in a different style, for differential fuzzing."""
import hashlib, ipaddress, json

DOC = ipaddress.IPv6Network('2001:db8::/32')

def canon_addr(v):
    return str(ipaddress.IPv6Address(v))

def canon_net(b):
    return str(ipaddress.IPv6Address(b)) + '/64'

def parse_addr(s):
    if not isinstance(s, str) or s == '' or '%' in s:
        return None
    if any(c in ' \t\n\r\x0b\x0c' for c in s):
        return None
    try:
        a = ipaddress.IPv6Address(s)
    except Exception:
        return None
    if a not in DOC:
        return None
    return int(a)

def plan_from_manifest(m):
    """Return list of probe dicts in plan order (independent of submission)."""
    out = []
    for w in sorted(m['windows'], key=lambda x: x['id']):
        q = 0
        for sc in sorted(w['scopes'], key=lambda x: x['id']):
            net = ipaddress.IPv6Network(sc['prefix'], strict=True)
            base = int(net.network_address)
            subs = sorted(sc['subnets']) if net.prefixlen == 56 else [0]
            for sub in subs:
                b = base + (sub << 64) if net.prefixlen == 56 else base
                c64 = canon_net(b)
                msg = ('ipv6-evidence-v1\n' + str(m['seed']) + '\n' + w['id'] + '\n'
                       + sc['id'] + '\n' + c64 + '\n').encode('ascii')
                c0 = int.from_bytes(hashlib.sha256(msg).digest()[:8], 'big') | (1 << 63)
                entries = [('low', i, i) for i in range(1, m['low_count'] + 1)]
                entries.append(('canary', c0, 0))
                entries.append(('canary', c0 ^ 1, 1))
                for role, iid, slot in entries:
                    for att in range(m['attempts']):
                        label = ('low-%d' % iid) if role == 'low' else ('canary-%d' % slot)
                        pid = w['id'] + '/' + sc['id'] + '/' + str(sub) + '/' + label + '/' + str(att)
                        sent = w['start_ms'] + q * m['spacing_ms']
                        out.append({'id': pid, 'window': w['id'], 'scope': sc['id'], 'subnet': sub,
                                    'target_int': b | iid, 'role': role, 'slot': slot, 'attempt': att,
                                    'sent_ms': sent, 'deadline_ms': sent + m['timeout_ms']})
                        q += 1
    return out

def _load_json(text):
    """JSON decode with duplicate-key and nonfinite rejection; raises ValueError."""
    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise ValueError('dup')
            d[k] = v
        return d
    def num(s):
        f = float(s)
        if f != f or f in (float('inf'), float('-inf')):
            raise ValueError('nonfinite')
        return f
    return json.loads(text, object_pairs_hook=hook, parse_constant=lambda s: (_ for _ in ()).throw(ValueError('nf')),
                      parse_float=num)

def is_int(v):
    return type(v) is int

def ref_replay(m, raw_lines):
    """raw_lines: list of bytes (no LF). Returns the expected replay object."""
    probes = plan_from_manifest(m)
    by_id = {p['id']: p for p in probes}
    segments = []
    for p in probes:
        key = (p['window'], p['scope'], p['subnet'])
        if key not in [ (s[0], s[1], s[2]) for s in segments ]:
            pass
    # segment list in plan order
    seen = set()
    for p in probes:
        k = (p['window'], p['scope'], p['subnet'])
        if k not in seen:
            seen.add(k)
            segments.append(k)
    base_of = {}
    for p in probes:
        base_of[(p['window'], p['scope'], p['subnet'])] = p['target_int'] & ~((1 << 64) - 1) if p['role'] == 'low' else p['target_int'] & ~((1 << 64) - 1)
    # note: base = target & ~(2^64-1) works because iid < 2^64
    accepted = []      # list of dicts with probe ref and fields
    seen_tuples = set()
    dup = 0
    acc = 0
    diags = []
    for i, raw in enumerate(raw_lines, start=1):
        reason = None
        obj = None
        try:
            text = raw.decode('utf-8')
            if text.startswith('﻿'):
                raise ValueError('bom')
            obj = _load_json(text)
        except Exception:
            reason = 'json'
        if reason is None:
            if not isinstance(obj, dict) or set(obj.keys()) != {'probe_id','received_ms','target','source','type','code'}:
                reason = 'schema'
            elif not isinstance(obj['probe_id'], str) or obj['probe_id'] == '' or len(obj['probe_id']) > 200:
                reason = 'schema'
            elif not isinstance(obj['target'], str) or not isinstance(obj['source'], str):
                reason = 'schema'
            elif not all(is_int(obj[k]) for k in ('received_ms','type','code')):
                reason = 'schema'
        tgt = src = None
        if reason is None:
            tgt = parse_addr(obj['target'])
            src = parse_addr(obj['source'])
            if tgt is None or src is None:
                reason = 'address'
        pr = None
        if reason is None:
            pr = by_id.get(obj['probe_id'])
            if pr is None:
                reason = 'unknown_probe'
        if reason is None and tgt != pr['target_int']:
            reason = 'target_mismatch'
        if reason is None and not (pr['sent_ms'] <= obj['received_ms'] < pr['deadline_ms']):
            reason = 'time'
        if reason is None:
            t, c = obj['type'], obj['code']
            if not ((t == 129 and c == 0) or (t == 1 and 0 <= c <= 6)):
                reason = 'icmp'
        if reason is not None:
            diags.append({'line': i, 'reason': reason})
            continue
        tup = (pr['id'], obj['received_ms'], tgt, src, obj['type'], obj['code'])
        if tup in seen_tuples:
            dup += 1
        else:
            seen_tuples.add(tup)
            acc += 1
            accepted.append({'probe': pr, 'received': obj['received_ms'], 'target': tgt,
                             'source': src, 'type': obj['type'], 'code': obj['code']})
    # evidence
    out_segments = []
    for (wid, sid, sub) in segments:
        base = None
        for p in probes:
            if (p['window'], p['scope'], p['subnet']) == (wid, sid, sub):
                base = p['target_int'] & ~((1 << 64) - 1)
                break
        canary_hit = set()
        internal = set()
        external = set()
        per_target = {}   # iid -> {attempt: {'int':bool,'ext':bool,'src':set,'any':bool}}
        for a in accepted:
            pr = a['probe']
            if (pr['window'], pr['scope'], pr['subnet']) != (wid, sid, sub):
                continue
            if pr['role'] == 'canary':
                if a['type'] == 129 and a['code'] == 0 and a['source'] == a['target']:
                    canary_hit.add(pr['slot'])
            else:
                slot = per_target.setdefault(pr['slot'], {})
                rec = slot.setdefault(pr['attempt'], {'int': False, 'ext': False, 'src': set(), 'any': False})
                rec['any'] = True
                if a['type'] == 129 and a['code'] == 0 and a['source'] == a['target']:
                    rec['int'] = True
                if a['type'] == 1 and a['source'] != a['target']:
                    rec['ext'] = True
                    rec['src'].add(a['source'])
        for iid, atts in per_target.items():
            if any(r['int'] for r in atts.values()):
                internal.add(base | iid)
            for r in atts.values():
                external |= r['src']
        overlap = internal & external
        if 0 in canary_hit and 1 in canary_hit:
            state = 'alias_suspect'
        elif overlap:
            state = 'ambiguous'
        else:
            state = 'usable'
        exposure = 'excluded' if state != 'usable' else ('observed_internal_reply' if internal else 'inconclusive')
        targets = []
        for iid in range(1, m['low_count'] + 1):
            atts = per_target.get(iid, {})
            ia = sorted(a for a, r in atts.items() if r['int'])
            ea = sorted(a for a, r in atts.items() if r['ext'])
            es = sorted(set().union(*[r['src'] for r in atts.values()])) if atts else []
            silent = [a for a in range(m['attempts']) if a not in atts]
            if state == 'alias_suspect':
                cl = 'alias_suspect'
            elif state == 'ambiguous':
                cl = 'ambiguous'
            elif ia and ea:
                cl = 'mixed'
            elif ia:
                cl = 'internal'
            elif ea:
                cl = 'external'
            else:
                cl = 'unknown'
            targets.append({'address': canon_addr(base | iid), 'classification': cl,
                            'internal_attempts': ia, 'external_attempts': ea,
                            'external_sources': [canon_addr(v) for v in es],
                            'silent_attempts': silent})
        out_segments.append({'window': wid, 'scope': sid, 'subnet': sub,
                             'network': canon_net(base), 'state': state, 'exposure': exposure,
                             'canary_hits': sorted(canary_hit),
                             'internal': [canon_addr(v) for v in sorted(internal)],
                             'external': [canon_addr(v) for v in sorted(external)],
                             'overlap': [canon_addr(v) for v in sorted(overlap)],
                             'targets': targets})
    return {'version': 1, 'accepted_rows': acc, 'duplicate_rows': dup,
            'diagnostics': diags, 'segments': out_segments}
